func maxDetona(bombas [][]int) int {
	nu := len(bombas)
	adjun := make([][]int, nu)
    for i := 0; i < nu; i++ {
        for j := 0; j < nu; j++ {
            if i == j {
                continue
            }
            xi, yi, ri := int64(bombas[i][0]), int64(bombas[i][1]), int64(bombas[i][2])
            xj, yj := int64(bombas[j][0]), int64(bombas[j][1])

            dis := (xi-xj)*(xi-xj) + (yi-yj)*(yi-yj)
            if dis <= ri*ri {
                adjun[i] = append(adjun[i], j)
            }
        }
    }
}

for i := 0; i < nu; i++ {
	for j := 0; j < nu; j++ {
		if i == j {
			continue
		}
		xi, yi, ri := int64(bombas[i][0]), int64(bombas[i][1]), int64(bombas[i][2])
		xj, yj := int64(bombas[j][0]), int64(bombas[j][1])

		dis := (xi-xj)*(xi-xj) + (yi-yj)*(yi-yj)
		if dis <= ri*ri {
			adjun[i] = append(adjun[i], j)
		}
	}
}

maxbomba := 0
for i := 0; i < nu; i++ {
	visitado := make([]bool, nu)
	cont := 0
	var busca func(node int)
	busca = func(node int) {
		visitado[node] = true
		cont++
		for _, adj := range adjun[node] {
			if !visitado[adj] {
				busca(adj)
			}
		}
	}
	busca(i)
	if cont > maxbomba {
		maxbomba = cont
	}
	return maxbomba
}
